def _has_not_null_constraints() -> bool:
    """Postgres 18+ records each NOT NULL as a named constraint; earlier versions have none to rename."""
    if context.is_offline_mode():
        return True  # offline SQL is written for production, which runs Postgres 18
    return op.get_bind().dialect.server_version_info >= (18,)


def upgrade() -> None:
    for statement in UPGRADE:
        op.execute(statement)
    if _has_not_null_constraints():
        for statement in NOT_NULL_UPGRADE:
            op.execute(statement)


def downgrade() -> None:
    if _has_not_null_constraints():
        for statement in NOT_NULL_DOWNGRADE:
            op.execute(statement)
    for statement in DOWNGRADE:
        op.execute(statement)
